<script setup lang="ts">
import { onUnmounted, ref, watch } from "vue";
import { createSmsParserClient } from "../../workers/smsParserClient";
import type { SmsParserEdit } from "../../workers/smsParser.worker";
import { type SmsOriginCapabilities, type SmsParserDefinition, type SmsLiteralAmountRelation } from "@papilio/api";
import {useI18n} from "vue-i18n";
const props=defineProps<{capabilities:SmsOriginCapabilities;disabled:boolean}>();
const {t}=useI18n();
const model=defineModel<string>({required:true});
type LiteralField="credit_markers"|"debit_markers"|"clause_separators"|"reference_labels"|"rial_labels"|"toman_labels"|"grouping_separators";
type RelationField="deposit_relations"|"balance_relations";
const fields:{key:LiteralField;label:string}[]=[{key:"credit_markers",label:"credit"},{key:"debit_markers",label:"debit"},{key:"clause_separators",label:"separators"},{key:"reference_labels",label:"references"},{key:"rial_labels",label:"rial"},{key:"toman_labels",label:"toman"},{key:"grouping_separators",label:"grouping"}];
const relations:{key:RelationField;label:string}[]=[{key:"deposit_relations",label:"deposit"},{key:"balance_relations",label:"balance"}];
const data=ref<SmsParserDefinition|null>(null),validationError=ref(""),processing=ref(false);
const client=createSmsParserClient();let alive=true,sequence=0;
async function parse():Promise<void>{const key=++sequence;processing.value=true;validationError.value="";try{const reply=await client.compute({text:model.value,capabilities:props.capabilities});if(!alive||key!==sequence)return;data.value=reply.value;validationError.value=reply.error??"";}catch(cause){if(alive&&key===sequence)validationError.value=cause instanceof Error?cause.message:"Parser validation failed.";}finally{if(alive&&key===sequence)processing.value=false;}}
async function change(edit:SmsParserEdit):Promise<void>{if(props.disabled||processing.value||!data.value)return;const key=++sequence;processing.value=true;try{const reply=await client.compute({text:model.value,edit,capabilities:props.capabilities});if(!alive||key!==sequence)return;if(reply.text!==null)model.value=reply.text;else validationError.value=reply.error??"The parser definition could not be updated.";}catch(cause){if(alive&&key===sequence)validationError.value=cause instanceof Error?cause.message:"Parser update failed.";}finally{if(alive&&key===sequence)processing.value=false;}}
function text(event:Event):string{return (event.target as HTMLInputElement).value;}
function literal(key:LiteralField,index:number,event:Event):void{void change({field:key,operation:"set",index,value:text(event)});}
function addLiteral(key:LiteralField):void{if(!props.capabilities.capacity||!data.value||data.value[key].length>=props.capabilities.capacity.max_rules_per_field)return;void change({field:key,operation:"add",value:""});}
function addRelation(key:RelationField):void{if(!props.capabilities.capacity||!data.value||data.value[key].length>=props.capabilities.capacity.max_rules_per_field)return;void change({field:key,operation:"add",value:{marker:"",relation:props.capabilities.amount_relations[0]!,implicit_unit:null}});}
function rule(key:RelationField,index:number,field:keyof SmsLiteralAmountRelation,event:Event):void{const input=text(event);void change({field:key,operation:"set",index,member:field,value:(field==="implicit_unit"||field==="required_amount_suffix")&&input===""?null:input});}
watch(model,parse,{immediate:true});onUnmounted(()=>{alive=false;++sequence;client.close();});
</script>
<template>
<section v-if="data" class="form-grid" :aria-label="t('paymentConfig.parserEditor.title')"><label class="field"><span>{{t('paymentConfig.parserEditor.mode')}}</span><select :value="data.mode" :disabled="processing||disabled" @change="change({field:'mode',operation:'set',value:text($event)})"><option v-for="mode in capabilities.parser_modes" :key="mode" :value="mode">{{t(mode==='labelled_credit'?'paymentConfig.parserEditor.labelled':'paymentConfig.parserEditor.legacy')}}</option></select></label><label class="check-row"><input :checked="data.case_sensitive" type="checkbox" :disabled="processing||disabled" @change="change({field:'case_sensitive',operation:'set',value:($event.target as HTMLInputElement).checked})"/>{{t('paymentConfig.parserEditor.case')}}</label><section v-for="field in fields" :key="field.key" class="rule-section"><h4>{{t(`paymentConfig.parserEditor.${field.label}`)}}</h4><div v-for="(entry,index) in data[field.key]" :key="index" class="literal-row"><label class="field"><span>{{t(`paymentConfig.parserEditor.${field.label}`)}} {{index+1}}</span><textarea :value="entry" :maxlength="capabilities.capacity?.max_marker_chars" :disabled="processing||disabled" rows="1" required @input="literal(field.key,index,$event)"/></label><button type="button" class="btn small secondary" :disabled="processing||disabled" :aria-label="`${t('paymentConfig.parserEditor.remove')} ${t(`paymentConfig.parserEditor.${field.label}`)} ${index+1}`" @click="change({field:field.key,operation:'remove',index})">{{t('paymentConfig.parserEditor.remove')}}</button></div><button type="button" class="btn small secondary" :disabled="processing||disabled||!capabilities.capacity||data[field.key].length>=capabilities.capacity.max_rules_per_field" @click="addLiteral(field.key)">{{t('paymentConfig.parserEditor.addLiteral')}}</button></section><section v-for="field in relations" :key="field.key" class="rule-section"><h4>{{t(`paymentConfig.parserEditor.${field.label}`)}}</h4><div v-for="(entry,index) in data[field.key]" :key="index" class="form-grid amount-rule"><label class="field"><span>{{t('paymentConfig.parserEditor.literal',{index:index+1})}}</span><input :value="entry.marker" :maxlength="capabilities.capacity?.max_marker_chars" :disabled="processing||disabled" required @input="rule(field.key,index,'marker',$event)"/></label><label class="field"><span>{{t('paymentConfig.parserEditor.position')}}</span><select :value="entry.relation" :disabled="processing||disabled" @change="rule(field.key,index,'relation',$event)"><option v-for="relation in capabilities.amount_relations" :key="relation" :value="relation">{{t(relation==='label_before_amount'?'paymentConfig.parserEditor.beforeAmount':'paymentConfig.parserEditor.amountBefore')}}</option></select></label><label class="field"><span>{{t('paymentConfig.parserEditor.missingUnit')}}</span><select :value="entry.implicit_unit??''" :disabled="processing||disabled" @change="rule(field.key,index,'implicit_unit',$event)"><option value="">{{t('paymentConfig.parserEditor.requireUnit')}}</option><option v-for="unit in capabilities.units" :key="unit" :value="unit">{{t('paymentConfig.parserEditor.useUnit',{unit})}}</option></select></label><label class="field"><span>{{t('paymentConfig.parserEditor.suffix')}}</span><input :value="entry.required_amount_suffix??''" :maxlength="capabilities.capacity?.max_marker_chars" :disabled="processing||disabled" placeholder="e.g. +" @input="rule(field.key,index,'required_amount_suffix',$event)"/><small>{{t('paymentConfig.parserEditor.suffixHint')}}</small></label><button type="button" class="btn small secondary" :disabled="processing||disabled" @click="change({field:field.key,operation:'remove',index})">{{t('paymentConfig.parserEditor.removeRule')}}</button></div><button type="button" class="btn small secondary" :disabled="processing||disabled||!capabilities.capacity||data[field.key].length>=capabilities.capacity.max_rules_per_field" @click="addRelation(field.key)">{{t('paymentConfig.parserEditor.addAmount')}}</button></section></section>
<p v-if="processing" role="status">{{t('paymentConfig.parserEditor.validating')}}</p><p v-else-if="validationError" class="message error" role="alert">{{validationError}}</p><p class="hint-box">{{t('paymentConfig.parserEditor.separatorHint')}}</p>
</template>
<style scoped>.rule-section{border-top:1px solid var(--line);padding-top:12px}.literal-row{display:flex;align-items:end;gap:10px}.literal-row .field{flex:1;min-width:0}.amount-rule{padding:12px;margin-bottom:12px;border:1px solid var(--line);border-radius:var(--radius,12px)}</style>
